intentos.respuesta_cruda:
{
  "sql": "SELECT t.categoria_ingles, mala_calificacion, porcentaje_retrasos FROM ( SELECT c.product_category_name_english AS categoria_ingles, AVG(rv.review_score) AS mala_calificacion, AVG(CASE WHEN o.order_delivered_customer_date > o.order_estimated_delivery_date THEN 1 ELSE 0 END) AS porcentaje_retrasos FROM vw_ventas_pedido o JOIN order_reviews rv ON o.order_id = rv.order_id LEFT JOIN product_category_translation c ON c.product_category_name = o.product_category_name WHERE o.order_status IN ('delivered') GROUP BY c.product_category_name_english ) t WHERE t.mala_calificacion < ( SELECT AVG(review_score) FROM order_reviews WHERE order_id IN ( SELECT order_id FROM vw_pedidos_validos ) ) AND t.porcentaje_retrasos < ( SELECT AVG(CASE WHEN order_delivered_customer_date > order_estimated_delivery_date THEN 1 ELSE 0 END) FROM vw_pedidos_validos WHERE order_status = 'delivered' )"
}
